sys_script.script:
(function executeRule(current, previous) {
    var status = current.getValue('status');
    var prevStatus = previous ? previous.getValue('status') : '';
    if (status === prevStatus) return;

    // Approver/stage-reviewer identity and timestamps are set explicitly by BjitLeaveApproval
    // before this record is saved; this rule only maintains the leave balance.
    if (status === 'approved' && prevStatus !== 'approved') {
        // Update leave balance - add to used, subtract from remaining
        var duration = parseFloat(current.getValue('duration') || '0');
        var year = new GlideDateTime().getYearLocalTime();
        var balGr = new GlideRecord('x_2316161_bjit_e_0_lv_bal');
        balGr.addQuery('employee', current.getValue('employee'));
        balGr.addQuery('leave_type', current.getValue('leave_type'));
        balGr.addQuery('year', year);
        balGr.query();
        if (balGr.next()) {
            var used = parseFloat(balGr.getValue('used_days') || '0');
            var pending = parseFloat(balGr.getValue('pending_days') || '0');
            var entitled = parseFloat(balGr.getValue('entitled_days') || '0');
            var carried = parseFloat(balGr.getValue('carried_days') || '0');
            balGr.setValue('used_days', (used + duration).toFixed(1));
            balGr.setValue('pending_days', Math.max(0, pending - duration).toFixed(1));
            balGr.setValue('remaining_days', (entitled + carried - used - duration - Math.max(0, pending - duration)).toFixed(1));
            balGr.update();
        }
    }

    if (status === 'rejected') {
        // Remove from pending
        var dur = parseFloat(current.getValue('duration') || '0');
        var yr = new GlideDateTime().getYearLocalTime();
        var bGr = new GlideRecord('x_2316161_bjit_e_0_lv_bal');
        bGr.addQuery('employee', current.getValue('employee'));
        bGr.addQuery('leave_type', current.getValue('leave_type'));
        bGr.addQuery('year', yr);
        bGr.query();
        if (bGr.next()) {
            var pend = parseFloat(bGr.getValue('pending_days') || '0');
            var ent = parseFloat(bGr.getValue('entitled_days') || '0');
            var car = parseFloat(bGr.getValue('carried_days') || '0');
            var use = parseFloat(bGr.getValue('used_days') || '0');
            bGr.setValue('pending_days', Math.max(0, pend - dur).toFixed(1));
            bGr.setValue('remaining_days', (ent + car - use - Math.max(0, pend - dur)).toFixed(1));
            bGr.update();
        }
    }

    if (status === 'cancelled' && (prevStatus === 'pending' || prevStatus === 'draft')) {
        // Remove from pending
        var durC = parseFloat(current.getValue('duration') || '0');
        var yrC = new GlideDateTime().getYearLocalTime();
        var bcGr = new GlideRecord('x_2316161_bjit_e_0_lv_bal');
        bcGr.addQuery('employee', current.getValue('employee'));
        bcGr.addQuery('leave_type', current.getValue('leave_type'));
        bcGr.addQuery('year', yrC);
        bcGr.query();
        if (bcGr.next()) {
            var pendC = parseFloat(bcGr.getValue('pending_days') || '0');
            var entC = parseFloat(bcGr.getValue('entitled_days') || '0');
            var carC = parseFloat(bcGr.getValue('carried_days') || '0');
            var useC = parseFloat(bcGr.getValue('used_days') || '0');
            bcGr.setValue('pending_days', Math.max(0, pendC - durC).toFixed(1));
            bcGr.setValue('remaining_days', (entC + carC - useC - Math.max(0, pendC - durC)).toFixed(1));
            bcGr.update();
        }
    }
})(current, previous);
